Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
perf/x86/intel/uncore: Fix die ID init and look up bugs

In snbep_pci2phy_map_init(), in the nr_node_ids > 8 path,
uncore_device_to_die() may return -1 when all CPUs associated
with the UBOX device are offline.

Remove the WARN_ON_ONCE(die_id == -1) check for two reasons:

- The current code breaks out of the loop. This is incorrect because
  pci_get_device() does not guarantee iteration in domain or bus order,
  so additional UBOX devices may be skipped during the scan.

- Returning -EINVAL is incorrect, since marking offline buses with
  die_id == -1 is expected and should not be treated as an error.

Separately, when NUMA is disabled on a NUMA-capable platform,
pcibus_to_node() returns NUMA_NO_NODE, causing uncore_device_to_die()
to return -1 for all PCI devices.  As a result,
spr_update_device_location(), used on Intel SPR and EMR, ignores the
corresponding PMON units and does not add them to the RB tree.

Fix this by using uncore_pcibus_to_dieid(), which retrieves topology
from the UBOX GIDNIDMAP register and works regardless of whether NUMA
is enabled in Linux.  This requires snbep_pci2phy_map_init() to be
added in spr_uncore_pci_init().

Keep uncore_device_to_die() only for the nr_node_ids > 8 case, where
NUMA is expected to be enabled.

Fixes: 9a7832ce3d92 ("perf/x86/intel/uncore: With > 8 nodes, get pci bus die id from NUMA info")
Fixes: 65248a9a9ee1 ("perf/x86/uncore: Add a quirk for UPI on SPR")
Signed-off-by: Zide Chen <zide.chen@intel.com>
Signed-off-by: Peter Zijlstra (Intel) <peterz@infradead.org>
Reviewed-by: Dapeng Mi <dapeng1.mi@linux.intel.com>
Tested-by: Steve Wahl <steve.wahl@hpe.com>
Link: https://patch.msgid.link/20260313174050.171704-4-zide.chen@intel.com

Here is the root cause:
uncore_device_to_die() relies on pcibus_to_node() which returns NUMA_NO_NODE when NUMA is disabled, causing die ID lookup to fail with -1 and skip PMON units. Additionally, in the path for >8 nodes, offline CPUs cause the same -1 return, and the flawed error handling with WARN_ON_ONCE and break prematurely stops scanning other UBOX devices.

Here is the patch:
  */
 static int snbep_pci2phy_map_init(int devid, int nodeid_loc, int idmap_loc, bool reverse)
 {
 	struct pci_dev *ubox_dev = NULL;
 	int i, bus, nodeid, segment, die_id;
 	struct pci2phy_map *map;
 	int err = 0;
 	u32 config = 0;

 	while (1) {
 		/* find the UBOX device */
 		ubox_dev = pci_get_device(PCI_VENDOR_ID_INTEL, devid, ubox_dev);
 		if (!ubox_dev)
 			break;
 		bus = ubox_dev->bus->number;
 		/*
 		 * The nodeid and idmap registers only contain enough
 		 * information to handle 8 nodes.  On systems with more
 		 * than 8 nodes, we need to rely on NUMA information,
 		 * filled in from BIOS supplied information, to determine
 		 * the topology.
 		 */
 		if (nr_node_ids <= 8) {
 			err = upi_nodeid_groupid(ubox_dev, nodeid_loc, idmap_loc,
 						 &nodeid, &config);
 			if (err)
 				break;

 			segment = pci_domain_nr(ubox_dev->bus);
 			raw_spin_lock(&pci2phy_map_lock);
 			map = __find_pci2phy_map(segment);
 			if (!map) {
 				raw_spin_unlock(&pci2phy_map_lock);
 				err = -ENOMEM;
 				break;
 			}

 			map->pbus_to_dieid[bus] = topology_gidnid_map(nodeid, config);
 			raw_spin_unlock(&pci2phy_map_lock);
 		} else {
 			segment = pci_domain_nr(ubox_dev->bus);
 			raw_spin_lock(&pci2phy_map_lock);
 			map = __find_pci2phy_map(segment);
 			if (!map) {
 				raw_spin_unlock(&pci2phy_map_lock);
 				err = -ENOMEM;
 				break;
 			}

 			map->pbus_to_dieid[bus] = die_id = uncore_device_to_die(ubox_dev);
-
 			raw_spin_unlock(&pci2phy_map_lock);
-
-			if (WARN_ON_ONCE(die_id == -1)) {
-				err = -EINVAL;
-				break;
-			}
 		}
 	}

 	if (!err) {
 		/*
 		 * For PCI bus with no UBOX device, find the next bus
 		 * that has UBOX device and use its mapping.
 		 */
 		raw_spin_lock(&pci2phy_map_lock);
 		list_for_each_entry(map, &pci2phy_map_head, list) {
 			i = -1;
 			if (reverse) {
 				for (bus = 255; bus >= 0; bus--) {
 					if (map->pbus_to_dieid[bus] != -1)
 						i = map->pbus_to_dieid[bus];
 					else
 						map->pbus_to_dieid[bus] = i;
 				}
 			} else {
 				for (bus = 0; bus <= 255; bus++) {
 					if (map->pbus_to_dieid[bus] != -1)
 						i = map->pbus_to_dieid[bus];
 					else
 						map->pbus_to_dieid[bus] = i;
 				}
 			}
 		}
 		raw_spin_unlock(&pci2phy_map_lock);
 	}

 	pci_dev_put(ubox_dev);

 	return pcibios_err_to_errno(err);
 }


 static void spr_update_device_location(int type_id)
 {
 	struct intel_uncore_discovery_unit *unit;
 	struct intel_uncore_type *type;
 	struct pci_dev *dev = NULL;
 	struct rb_root *root;
 	u32 device, devfn;
 	int die;

 	if (type_id == UNCORE_SPR_UPI) {
 		type = &spr_uncore_upi;
 		device = SPR_UNCORE_UPI_PCIID;
 		devfn = SPR_UNCORE_UPI0_DEVFN;
 	} else if (type_id == UNCORE_SPR_M3UPI) {
 		type = &spr_uncore_m3upi;
 		device = SPR_UNCORE_M3UPI_PCIID;
 		devfn = SPR_UNCORE_M3UPI0_DEVFN;
 	} else
 		return;

 	root = kzalloc_obj(struct rb_root);
 	if (!root) {
 		type->num_boxes = 0;
 		return;
 	}
 	*root = RB_ROOT;

 	while ((dev = pci_get_device(PCI_VENDOR_ID_INTEL, device, dev)) != NULL) {

-		die = uncore_device_to_die(dev);
+		die = uncore_pcibus_to_dieid(dev->bus);
 		if (die < 0)
 			continue;

 		unit = kzalloc_obj(*unit);
 		if (!unit)
 			continue;
 		unit->die = die;
 		unit->id = PCI_SLOT(dev->devfn) - PCI_SLOT(devfn);
 		unit->addr = pci_domain_nr(dev->bus) << UNCORE_DISCOVERY_PCI_DOMAIN_OFFSET |
 			     dev->bus->number << UNCORE_DISCOVERY_PCI_BUS_OFFSET |
 			     devfn << UNCORE_DISCOVERY_PCI_DEVFN_OFFSET |
 			     type->box_ctl;

 		unit->pmu_idx = unit->id;

 		uncore_find_add_unit(unit, root, NULL);
 	}

 	type->boxes = root;
 }

 int spr_uncore_pci_init(void)
 {
+	int ret = snbep_pci2phy_map_init(0x3250, SKX_CPUNODEID, SKX_GIDNIDMAP, true);
+
+	if (ret)
+		return ret;
+
 	/*
 	 * The discovery table of UPI on some SPR variant is broken,
 	 * which impacts the detection of both UPI and M3UPI uncore PMON.
 	 * Use the pre-defined UPI and M3UPI table to replace.
 	 *
 	 * The accurate location, e.g., domain and BUS number,
 	 * can only be retrieved at load time.
 	 * Update the location of UPI and M3UPI.
 	 */
 	spr_update_device_location(UNCORE_SPR_UPI);
 	spr_update_device_location(UNCORE_SPR_M3UPI);
 	uncore_pci_uncores = uncore_get_uncores(UNCORE_ACCESS_PCI,
 						UNCORE_SPR_PCI_EXTRA_UNCORES,
 						spr_pci_uncores,
 						UNCORE_SPR_NUM_UNCORE_TYPES,
 						spr_uncores);
 	return 0;
 }



